{% assign badges = product.metafields.custom.badges.value %}
{% assign _lc = localization.language.iso_code | default: shop.locale | default: 'EN' | upcase %}

{% if badges != blank %}
  <div class="cj-custom-badge-list">
    {% for badge in badges %}
      {% assign badge_raw = badge | strip %}
      {% assign badge_key = badge_raw | upcase %}

      {% case badge_key %}
        {% when 'NEW' %}
          {% case _lc %}
            {% when 'NL' %}
              {% assign badge_text = 'NIEUW' %}
            {% when 'DE' %}
              {% assign badge_text = 'NEU' %}
            {% else %}
              {% assign badge_text = 'NEW' %}
          {% endcase %}
        {% else %}
          {% assign badge_text = badge_raw %}
      {% endcase %}

      <span class="cj-custom-badge">
        {{ badge_text }}
      </span>
    {% endfor %}
  </div>
{% endif %}

<style>
  /* Hide native Impact badge placement on PDP */
  .product-info__badge-list {
    display: none !important;
  }

  .cj-custom-badge-list {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin: 0 0 12px;
  }

  .cj-custom-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 24px;
    padding: 0 9px;
    border-radius: 999px;
    background: #111;
    color: #fff;
    font-family: inherit;
    font-size: 10px;
    line-height: 1;
    font-weight: 400;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    white-space: nowrap;
  }

  @media (max-width: 768px) {
    .cj-custom-badge-list {
      margin: 0px 0 10px;
    }

    .cj-custom-badge {
      min-height: 22px;
      padding: 0 8px;
      font-size: 10px;
    }
  }
</style>

{%- assign path = request.path | downcase -%}
{%- assign locale_code = localization.language.iso_code | default: shop.locale | default: 'en' | downcase -%}

{%- assign shipping_note = 'Free shipping over $100 • Free exchanges' -%}
{%- if path contains '/nl' or locale_code contains 'nl' -%}
  {%- assign shipping_note = 'Gratis verzending vanaf €100 • Gratis omruilen' -%}
{%- elsif path contains '/de' or locale_code contains 'de' -%}
  {%- assign shipping_note = 'Kostenloser Versand ab 100 € • Kostenloser Umtausch' -%}
{%- endif -%}

<div class="us-shipping-note">
  {{ shipping_note }}
</div>

<style>
  .us-shipping-note {
    margin-top: 16px;
margin-bottom: 16px;
    text-align: center;
    font-size: 13px;
    line-height: 1.4;
    color: rgba(0, 0, 0, 0.65);
  }

  @media (max-width: 768px) {
    .us-shipping-note {
      font-size: 12.5px;
    }
  }
</style>

{% assign sale_enabled = product.metafields.custom.sale_enabled.value | default: false %}

{% if sale_enabled %}

<div class="cj-bundle-simple">

  <!-- Title -->
  <div class="cj-bundle-simple-title">
    {% if request.path contains '/nl' %}
      Summer sale
    {% elsif request.path contains '/de' %}
      Summer sale
    {% else %}
      Summer sale
    {% endif %}
  </div>

  {% assign discount_1 = 30 %}
  {% assign discount_2 = 40 %}
  {% assign discount_3 = 50 %}

  <!-- Offer lines -->
  <div class="cj-bundle-simple-lines">

    {% if request.path contains '/nl' %}

      <div>• 2 jeans = <strong>{{ discount_2 }}% korting</strong></div>
      <div>• 3 jeans = <strong>{{ discount_3 }}% korting</strong></div>
      <div class="cj-bundle-auto">
        Mix & Match · Automatische korting
      </div>

    {% elsif request.path contains '/de' %}

      <div>• 1 Jeans = <strong>{{ discount_1 }}% Rabatt</strong></div>
      <div>• 2 Jeans = <strong>{{ discount_2 }}% Rabatt</strong></div>
      <div>• 3 Jeans = <strong>{{ discount_3 }}% Rabatt</strong></div>
      <div class="cj-bundle-auto">
        Kombinieren & sparen · Automatischer Rabatt
      </div>

    {% else %}

      <div>• 1 jean = <strong>{{ discount_1 }}% off</strong></div>
      <div>• 2 jeans = <strong>{{ discount_2 }}% off</strong></div>
      <div>• 3 jeans = <strong>{{ discount_3 }}% off</strong></div>
      <div class="cj-bundle-auto">
        Mix & Match · Automatic Discount
      </div>

    {% endif %}

  </div>

</div>

<style>
.cj-bundle-simple{
  background:#F7EFE5;
  border-radius:10px;
  padding:10px 12px;
  margin:12px 0 16px;
}

.cj-bundle-simple-title{
  font-size:15px;
  font-weight:600;
  color:#111;
  margin-bottom:0;
}

.cj-bundle-simple-lines{
  font-size:14px;
  color:#111;
  line-height:1.45;
}

.cj-bundle-simple-lines strong{
  font-weight:700;
}

.cj-bundle-auto{
  color:#7f7f7f;
  font-weight:400;
  font-size:12px;
  margin-top:4px;
}

@media (max-width:600px){

  .cj-bundle-simple-title{
    font-size:15px;
  }

  .cj-bundle-simple-lines{
    font-size:13px;
  }

}
</style>

{% endif %}

{% assign sale_enabled = product.metafields.custom.sale_enabled.value | default: false %}

{% unless sale_enabled %}
  <div style="height:16px;"></div>
{% endunless %}

{%- assign path = request.path | downcase -%}
{%- assign locale_code = localization.language.iso_code | default: shop.locale | default: 'en' | downcase -%}

{%- assign customers_say_label = 'Customers say:' -%}
{%- if path contains '/nl' or locale_code contains 'nl' -%}
  {%- assign customers_say_label = 'Klanten zeggen:' -%}
{%- elsif path contains '/de' or locale_code contains 'de' -%}
  {%- assign customers_say_label = 'Kundinnen sagen:' -%}
{%- endif -%}

<div class="cj-customers-say">
  <strong>{{ customers_say_label }}</strong>
  <div class="cj-customers-say__value">
    {{ product.metafields.shopify.fit | metafield_tag: field: 'label' }}
  </div>
</div>

<style>
  .cj-customers-say{
    margin:0 0 16px;
    font-size:14px;
    line-height:1.35;
    color:#111;
  }

  .cj-customers-say__value{
    margin-top:4px;
  }

  .cj-customers-say__value,
  .cj-customers-say__value *{
    display:block;
    margin-bottom:0;
  }
</style>

{% if product %}
<style>
  :root{ --curv-border: rgba(17,17,17,.08); --row-pad-y:14px; --chev-size:24px; --chev-icon:10px; }

  .cj-reviews-acc{ color:#000; margin:0; border-top:1px solid var(--curv-border); }
  .cj-reviews-acc__head{ display:flex; align-items:center; justify-content:space-between; padding:var(--row-pad-y) 0; line-height:1; cursor:pointer; }
  .cj-reviews-acc__title{ font-weight:700; color:#000; }
  .cj-reviews-acc__chevbtn{ width:var(--chev-size); height:var(--chev-size); border-radius:999px; background:#EDEDED; display:inline-flex; align-items:center; justify-content:center; flex:0 0 auto; }
  .cj-reviews-acc__chev{ width:var(--chev-icon); height:var(--chev-icon); stroke:#000; stroke-width:2.6; stroke-linecap:round; stroke-linejoin:round; fill:none; transition:transform .2s ease; }
  .cj-reviews-acc.is-open .cj-reviews-acc__chev{ transform:rotate(180deg); }
  .cj-reviews-acc__panel[hidden]{ display:none !important; }
  .cj-reviews-acc__panel{ padding:0 0 16px; }
</style>

<section class="cj-reviews-acc" id="cj-reviews-acc" data-open="false" role="group" aria-label="Reviews">
  <div class="cj-reviews-acc__head" role="button" tabindex="0" aria-controls="cj-reviews-panel" aria-expanded="false">
    <span class="cj-reviews-acc__title">Reviews</span>
    <span class="cj-reviews-acc__chevbtn" aria-hidden="true">
      <svg class="cj-reviews-acc__chev" viewBox="0 0 20 20"><path d="M5 8l5 5 5-5"/></svg>
    </span>
  </div>

  <div class="cj-reviews-acc__panel" id="cj-reviews-panel" hidden>
    <div id="ss-product-reviews-2"></div>
  </div>
</section>

<script>
(function(){
  var root = document.getElementById('cj-reviews-acc');
  if(!root) return;

  var head = root.querySelector('.cj-reviews-acc__head');
  var panel = root.querySelector('.cj-reviews-acc__panel');
  var startOpen = false;

  function setOpen(open){
    root.classList.toggle('is-open', open);
    head.setAttribute('aria-expanded', open ? 'true' : 'false');
    if(open){ panel.removeAttribute('hidden'); } 
    else { panel.setAttribute('hidden',''); }
  }

  setOpen(startOpen);

  head.addEventListener('click', function(){
    setOpen(!root.classList.contains('is-open'));
  });

  head.addEventListener('keydown', function(e){
    if(e.key === 'Enter' || e.key === ' '){
      e.preventDefault();
      setOpen(!root.classList.contains('is-open'));
    }
  });

  var ref = document.querySelector('.product-info__accordion .accordion__toggle');
  if (ref) {
    var cs = getComputedStyle(ref);
    var py = parseFloat(cs.paddingTop) || 16;
    root.style.setProperty('--row-pad-y', py + 'px');
  }

  root.style.marginTop = '0';
})();
</script>
{% endif %}
